/*
 * ai_mlp.c -- INT8 quantised two-layer MLP.
 *
 * Weight layout (generated by tools/train_mnist.py):
 *   AI_W1 : int8[AI_HIDDEN_SIZE][AI_INPUT_SIZE]  row-major, symmetric, zero point 0
 *   AI_W2 : int8[AI_CLASSES][AI_HIDDEN_SIZE]     row-major, symmetric, zero point 0
 *   AI_B1 : float[AI_HIDDEN_SIZE]
 *   AI_B2 : float[AI_CLASSES]
 *
 * Arithmetic (identical to the Python reference):
 *   x_q   = round_half_away(x/255 * 127)              -> 0..127
 *   acc1  = sum(w1_q * x_q)                           int32, exact
 *   h     = relu(acc1 * AI_W1_SCALE * AI_X_SCALE + b1)
 *   h_q   = clamp(round_half_away(h / AI_H_SCALE), 0, 127)
 *   logit = sum(w2_q * h_q) * AI_W2_SCALE * AI_H_SCALE + b2
 *
 * Cost on a 72 MHz Cortex-M3: 784x96 + 96x10 = 76k MAC, roughly 12-16 ms.
 */
#include "ai_mlp.h"

#include <math.h>
#include <stddef.h>

/* Round half away from zero -- must match round_half_away() in Python. */
static inline int32_t round_f2i(float v)
{
    return (int32_t)(v >= 0.0f ? (v + 0.5f) : (v - 0.5f));
}

static void softmax(const float *logits, float *probs, int n)
{
    float maxv = logits[0];
    int i;

    for (i = 1; i < n; i++) {
        if (logits[i] > maxv) {
            maxv = logits[i];
        }
    }

    float sum = 0.0f;
    for (i = 0; i < n; i++) {
        probs[i] = expf(logits[i] - maxv);
        sum += probs[i];
    }

    if (sum <= 0.0f) {
        sum = 1.0f;
    }
    for (i = 0; i < n; i++) {
        probs[i] /= sum;
    }
}

int ai_mlp_infer_logits(const uint8_t x[AI_INPUT_SIZE], float logits[AI_CLASSES],
                        float probs[AI_CLASSES])
{
    static int8_t x_q[AI_INPUT_SIZE];
    static int8_t h_q[AI_HIDDEN_SIZE];
    const float c1 = AI_W1_SCALE * AI_X_SCALE;
    int best = 0;
    int i, j;

    /* ---- quantise the input ------------------------------------------- */
    /* Two operations on purpose: Python does (u8 / 255) * 127, keeping the
     * same order guarantees identical rounding. */
    for (i = 0; i < AI_INPUT_SIZE; i++) {
        x_q[i] = (int8_t)round_f2i((float)x[i] / 255.0f * 127.0f);
    }

    /* ---- hidden layer -------------------------------------------------- */
    for (j = 0; j < AI_HIDDEN_SIZE; j++) {
        const int8_t *w = &AI_W1[j * AI_INPUT_SIZE];
        int32_t acc = 0;
        float h;
        int32_t q;

        for (i = 0; i < AI_INPUT_SIZE; i++) {
            acc += (int32_t)w[i] * (int32_t)x_q[i];
        }

        h = (float)acc * c1 + AI_B1[j];
        if (h < 0.0f) {
            h = 0.0f;
        }

        q = round_f2i(h / AI_H_SCALE);
        if (q < 0) {
            q = 0;
        } else if (q > 127) {
            q = 127;
        }
        h_q[j] = (int8_t)q;
    }

    /* ---- output layer -------------------------------------------------- */
    for (j = 0; j < AI_CLASSES; j++) {
        const int8_t *w = &AI_W2[j * AI_HIDDEN_SIZE];
        int32_t acc = 0;

        for (i = 0; i < AI_HIDDEN_SIZE; i++) {
            acc += (int32_t)w[i] * (int32_t)h_q[i];
        }

        logits[j] = (float)acc * (AI_W2_SCALE * AI_H_SCALE) + AI_B2[j];
        if (logits[j] > logits[best]) {
            best = j;
        }
    }

    if (probs != NULL) {
        softmax(logits, probs, AI_CLASSES);
    }

    return best;
}

int ai_mlp_infer(const uint8_t x[AI_INPUT_SIZE], float probs[AI_CLASSES])
{
    float logits[AI_CLASSES];
    return ai_mlp_infer_logits(x, logits, probs);
}
